PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    MotorLatch : BOOL := FALSE;
    EmergencyStopTimer : TON;
END_VAR

EmergencyStopTimer(IN := NOT EStop, PT := T#0s);

Motor := FALSE;

IF EStop THEN
    MotorLatch := FALSE;
    Motor := FALSE;
ELSIF Stop THEN
    MotorLatch := FALSE;
    Motor := FALSE;
ELSIF Start AND NOT EStop AND NOT Stop THEN
    MotorLatch := TRUE;
    Motor := TRUE;
END_IF;

