PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpTimer : TON;
END_VAR

IF Level <= LowLimit THEN
    PumpIn := TRUE;
ELSE
    PumpIn := FALSE;
END_IF;

IF Level >= HighLimit THEN
    ValveOut := TRUE;
ELSE
    ValveOut := FALSE;
END_IF;

// Safety rule enforcement
IF Level >= HighLimit AND PumpIn THEN
    PumpIn := FALSE;
END_IF;

END_PROGRAM

