END_IF;

IF PumpIn AND Level >= HighLimit THEN
    PumpIn := FALSE;
END_IF;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpTimer : TON;
END_VAR

// Check if the level is at or above the high limit
IF Level >= HighLimit THEN
    PumpIn := FALSE; // Turn off the pump to prevent overflow
    ValveOut := TRUE; // Open the outlet valve
ELSE
    IF Level <= LowLimit THEN
        PumpIn := TRUE; // Turn on the pump to fill the tank
        ValveOut := FALSE; // Close the outlet valve
    ELSE
        PumpIn := FALSE; // Keep the pump off
        ValveOut := FALSE; // Keep the outlet valve closed
    END_IF;
END_IF;

END_PROGRAM

