PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    HighLimit : INT := 90;
    LowLimit : INT := 10;
    PumpTimer : TON;
END_VAR

// Check if the level is at or above the high limit
IF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    // Check if the level is at or below the low limit
    IF Level <= LowLimit THEN
        PumpIn := TRUE;
        ValveOut := FALSE;
    ELSE
        // Hysteresis control for normal operation
        PumpIn := FALSE;
        ValveOut := FALSE;

        // Turn on the pump after the valve closes
        IF NOT ValveOut AND PumpTimer.Q THEN
            PumpIn := TRUE;
            PumpTimer(IN := FALSE, PT := T#1s);
        END_IF;

        // Prevent the pump from running while the level is at or above the high limit
        IF Level >= HighLimit THEN
            PumpIn := FALSE;
        END_IF;
    END_IF;
END_IF;

END_PROGRAM

