PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    DoorA_Open : BOOL := FALSE;
    DoorB_Open : BOOL := FALSE;
    PriorityTimer : TON;
END_VAR

PriorityTimer(IN := OpenA_Cmd OR OpenB_Cmd, PT := T#0s);

IF PriorityTimer.Q THEN
    IF OpenA_Cmd AND NOT OpenB_Cmd THEN
        DoorA := TRUE;
        DoorB := FALSE;
    ELSIF OpenB_Cmd AND NOT OpenA_Cmd THEN
        DoorA := FALSE;
        DoorB := TRUE;
    ELSE
        DoorA := FALSE;
        DoorB := FALSE;
    END_IF;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    OpenA_Timer : TON;
    OpenB_Timer : TON;
    Last_OpenA_Cmd : BOOL := FALSE;
    Last_OpenB_Cmd : BOOL := FALSE;
END_VAR

// Initialize timers
OpenA_Timer(IN := FALSE, PT := T#0s);
OpenB_Timer(IN := FALSE, PT := T#0s);

DoorA := FALSE;
DoorB := FALSE;

// Check if any new command has been received
IF OpenA_Cmd <> Last_OpenA_Cmd THEN
    OpenA_Timer(IN := OpenA_Cmd, PT := T#0s);
END_IF;

IF OpenB_Cmd <> Last_OpenB_Cmd THEN
    OpenB_Timer(IN := OpenB_Cmd, PT := T#0s);
END_IF;

Last_OpenA_Cmd := OpenA_Cmd;
Last_OpenB_Cmd := OpenB_Cmd;

// Implement the logic for opening doors
IF OpenA_Cmd AND NOT OpenB_Cmd AND OpenA_Timer.Q THEN
    DoorA := TRUE;
    DoorB := FALSE;
ELSIF OpenB_Cmd AND NOT OpenA_Cmd AND OpenB_Timer.Q THEN
    DoorA := FALSE;
    DoorB := TRUE;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;
END_PROGRAM

