PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    StopTimer : TON;
END_VAR

IF StartPB AND GuardClosed AND NOT Fault THEN
    Running := TRUE;
    StopTimer(IN := TRUE, PT := T#0s);
END_IF;

IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
    StopTimer(IN := FALSE, PT := T#0s);
END_IF;

Conveyor := Running AND NOT StopTimer.Q;

END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR
VAR_OUTPUT
    Conveyor : BOOL;
END_VAR
VAR
    Running : BOOL := FALSE;
    StartTimer : TON;
END_VAR

StartTimer(IN := StartPB AND GuardClosed AND NOT Fault, PT := T#0s);

IF StopPB OR NOT GuardClosed OR Fault THEN
    Running := FALSE;
ELSIF StartTimer.Q AND NOT Running THEN
    Running := TRUE;
END_IF;

Conveyor := Running;
END_PROGRAM

PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    ConveyorRunning : BOOL := FALSE;
    StartTimer : TON;
END_VAR

StartTimer(IN := StartPB AND GuardClosed AND NOT Fault, PT := T#0s);

Conveyor := ConveyorRunning OR StartTimer.Q;

IF StopPB OR NOT GuardClosed OR Fault THEN
    ConveyorRunning := FALSE;
ELSIF StartTimer.Q THEN
    ConveyorRunning := TRUE;
