PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR_INTERNAL
    State : INT := 0;
    T1 : TON;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

IF EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSE
    CASE State OF
        0: // Idle
            IF StartBatch AND Level >= LIQ_MIN THEN
                State := 1;
            END_IF;

        1: // Fill
            FillValve := TRUE;
            DrainValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            IF Level >= LVL_HIGH THEN
                State := 2;
            END_IF;

        2: // Heat
            FillValve := FALSE;
            DrainValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            IF Temp >= TEMP_SET THEN
                State := 3;
            END_IF;

        3: // React
            FillValve := FALSE;
            DrainValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            T1(IN := TRUE, PT := PT_REACT);
            IF NOT T1.Q THEN
                State := 4;
            END_IF;

        4: // Drain
            FillValve := FALSE;
            DrainValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR
    State : INT := 0;
    FillTimer : TON;
    ReactTimer : TON;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

FillTimer(IN := FillValve AND NOT EStop, PT := T#1s);
ReactTimer(IN := Heater AND Agitator AND NOT EStop, PT := T#1s);

CASE State OF
    0: -- Idle
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;

    1: -- Fill
        IF Level >= LVL_HIGH OR NOT EStop THEN
            State := 2;
        ELSE
            FillValve := TRUE;
        END_IF;

    2: -- Heat
        IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
            State := 3;
        END_IF;
        Heater := TRUE;
        Agitator := TRUE;

    3: -- React
        IF ReactTimer.Q THEN
            State := 4;
        END_IF;
        Heater := TRUE;
        Agitator := TRUE;

    4: -- Drain
        IF Level <= LVL_LOW AND NOT EStop THEN
            State := 0;
        ELSE
            DrainValve := TRUE;
        END_IF;

    ELSE: -- Default case should not happen
        State := 0;
END_CASE;

-- Safety conditions
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF NOT EStop THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

IF Level < LIQ_MIN AND (Heater OR Agitator) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

END_PROGRAM

