    // Toggle Lead state
    IF Lead = 0 THEN
        Lead := 1;
    ELSE
        Lead := 0;
    END_IF;
END_IF;

// Stop both pumps if EStop is activated
IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    // Assign output based on Lead state and Demand status
    IF Demand THEN
        IF Lead = 0 THEN
            Pump1 := TRUE;
            Pump2 := FALSE;
        ELSE
            Pump1 := FALSE;
            Pump2 := TRUE;
        END_IF;
