    T_Done(IN := FALSE);
ELSE
    IF NOT PrevTrigger AND Trigger THEN
        IF Count < CountLimit THEN
            Count := Count + 1;
        END_IF;
    END_IF;

    IF Count = CountLimit THEN
        T_Done(IN := TRUE);
    ELSE
        T_Done(IN := FALSE);
    END_IF;
END_IF;

Done := T_Done.Q;
